    "SHELL71" "RAPIER3" "RAPIER1" "WEASEL23" "LIGHTNING14" "WEASEL22" "LIGHTNING12" "KRAB31" "THUNDER22" "LIS42" "COBRA14" "TROLL12" "COBRA12" "COBRA11" "IRON13" "COBRA13" "BLADE14" "KRAB34"
